/* Types */
export type Address = {
	/**  The number and the street, in the order the country writes them. */
	street: string,
	postcode: string,
	city: string,
	region: string,
	/**  The whole of it on one line, as an envelope of the country carries it. */
	formatted: string,
};

export type AlgorithmFamily = "hmac" | "rsa" | "rsaPss" | "ecdsa" | "edDsa" | 
/**  `alg: none`: nothing signs it. */
"unsigned" | "unknown";

export type AppError = {
	code: ErrorCode,
	/**  Values to interpolate into the translated message, e.g. `{ "name": "Personal" }`. */
	params: { [key in string]: string },
	detail: string,
};

export type Attachment = {
	id: string,
	noteId: string,
	/**  The original name, the one displayed. Never used as a path. */
	fileName: string,
	mimeType: string,
	/**  `u32` and not `u64`: Specta refuses what JSON cannot carry without loss. */
	byteSize: number,
	createdAt: string,
};

/**
 *  One copy, as the interface lists it. `bytes` is `f64` because specta refuses the integer
 *  types JSON cannot carry exactly.
 */
export type Backup = {
	/**  The folder's name, which is its stamp, and what a restore asks for. */
	id: string,
	takenAt: string,
	/**  The database alone: the attachments are shared with the library and the other copies. */
	bytes: number | null,
	/**  Whether the key file travelled with it: without one, restoring loses the library. */
	openable: boolean,
};

export type Bank = {
	name: string,
	/**  None in a country that has no IBAN. */
	iban: string | null,
	bic: string | null,
	/**  What the country writes beside an IBAN or instead of one: a sort code, a routing number. */
	local: Identifier[],
};

export type Base64FileAnswer = 
/**  A file keeps the two Base64 alone: the other encodings of a megabyte are noise. */
{ kind: "encoded"; name: string; bytes: number; base64: string; base64Url: string } | { kind: "failed"; problem: FileProblem };

export type Birth = {
	/**  `YYYY-MM-DD`. */
	date: string,
	city: string,
	region: string,
};

export type BlockKind = "thisNetwork" | "private" | "sharedAddressSpace" | "loopback" | "linkLocal" | "documentation" | "benchmarking" | "multicast" | "reserved" | "broadcast" | "public" | "unspecified" | "ipv4Mapped" | "nat64" | "uniqueLocal" | "global" | 
/**  Wider than a special range it holds: no one sentence describes it. */
"mixed";

/**  What a tidy-up did, and what it takes to walk it back. */
export type BoardArrangement = {
	/**  What actually moved: a board already in order moves nothing, and opens no undo. */
	moved: number,
	previous: BoardLayout,
};

/**  A sub-folder named under a zone's title, opened by a click: the board draws one level. */
export type BoardChild = {
	id: string,
	name: string,
	colour: FolderColour,
	/**  What its whole sub-tree holds. */
	count: number,
};

export type BoardFrame = {
	x: number,
	y: number,
	width: number,
	height: number,
};

/**
 *  A whole board's geometry: every zone's frame and every loose card's place. What a tidy-up
 *  writes, and, read back first, what its undo puts back.
 */
export type BoardLayout = {
	zones: ZonePlacement[],
	cards: CardPlacement[],
};

/**  `flatten`: the front end draws this with the same card component the canvas uses. */
export type BoardNote = {
	/**
	 *  Dimmed in place rather than reflowed: spatial memory is what the board has that the
	 *  list view does not.
	 */
	matches: boolean,
	/**  `None` inside a zone, where a card flows; `Some` only on the free background. */
	position: BoardPoint | null,
} & DisplayNote;

export type BoardPoint = {
	x: number,
	y: number,
};

export type BoardQuery = {
	/**  Required, unlike `NotesQuery::space_id`: a board across every space has no zones. */
	spaceId: string,
	/**  The folder whose board this is, `None` for the space's: its sub-folders are the zones. */
	rootId?: string | null,
	search: string,
	filter: NoteFilter,
	tags: string[],
	languages: Language[],
	kinds: NoteKind[],
	priorities: Priority[],
	now: string,
};

/**
 *  How much of a board a tidy-up is allowed to move.
 * 
 *  Two scopes rather than one with a warning: what goes to pieces is the loose cards, and a
 *  zone placed and sized by hand is the only manual work the board holds.
 */
export type BoardScope = 
/**  The loose cards alone, flowed under the zones as they stand. */
"looseCards" | 
/**
 *  The zones as well: reading order, sized to their contents. Overwrites every frame
 *  set by hand.
 */
"everything";

export type BoardView = {
	zones: BoardZone[],
	loose: BoardNote[],
	/**
	 *  The space's, like `NotesView`'s: facets drawn from filtered notes would empty the
	 *  rails on the first selection.
	 */
	availableTags: string[],
	availableLanguages: Language[],
	isFiltering: boolean,
	matched: number,
	/**  The surface to pan over, sized from what is on it. */
	width: number,
	height: number,
};

export type BoardZone = {
	folder: Folder,
	frame: BoardFrame,
	/**  Every note of its sub-tree: a zone gathers what is under it. */
	notes: BoardNote[],
	children: BoardChild[],
};

export type BodyAnswer = {
	contentType: string | null,
	problem: JsonError | null,
	/**  Something is sent as the body of a `GET` or a `HEAD`: sent all the same, and said. */
	unusual: boolean,
};

export type ByteEncoding = "base64" | 
/**  `-` and `_` for `+` and `/`, without padding: what a URL or a JWT carries. */
"base64Url" | "base32" | "hex" | "binary" | "decimal";

/**  One of the last lines a card shows: what was written, and what it gave. */
export type CalcCardLine = {
	expression: string,
	value: CalcValue,
	aggregate: boolean,
};

/**  Why a line has no result. It stays on its line: the others go on computing. */
export type CalcError = 
/**  In UTF-16 units from the start of the line. */
{ kind: "unreadable"; at: number } | { kind: "unknownName"; name: string } | 
/**  `en = 5`: a word of the grammar is no name. */
{ kind: "reserved"; word: string } | 
/**  `distance + 3 Go`: a data size is no length. */
{ kind: "mismatch"; expected: Dimension; found: Dimension; unit: CalcUnit | null } | 
/**  ⚠️ No rate is fetched: the sheet works offline, and euros stay euros. */
{ kind: "currency" } | { kind: "notConvertible"; from: Dimension; to: CalcUnit | null } | { kind: "divisionByZero" } | 
/**  `total` with nothing to add up above it in the block. */
{ kind: "nothingAbove" } | 
/**  `préc` with no line above that gave a result. */
{ kind: "noPrevious" } | 
/**  A date moved by something other than whole days, months or years. */
{ kind: "dateShift" } | 
/**  An even root of a negative number. */
{ kind: "negativeRoot" } | 
/**  A logarithm of zero or less, or in a base of one or less. */
{ kind: "logDomain" } | 
/**  A base or a bitwise operation on a fraction. */
{ kind: "notWhole" } | 
/**  `ppi = 0`: a setting is above zero. */
{ kind: "notPositive" } | 
/**  `à 7`: a yearly rate is a percentage. */
{ kind: "rateExpected" } | { kind: "overflow" } | { kind: "unsupported" };

export type CalcLine = 
/**  Ends a block, as a heading does. */
{ kind: "blank" } | { kind: "heading"; title: string } | { kind: "comment" } | 
/**  Words with no number in them: a sentence, not a mistake. */
{ kind: "text" } | { kind: "value"; value: CalcValue; 
/**  The variable the line names, `prix` in `prix = 120 €`. */
name: string | null; 
/**  `total` or `moyenne`: drawn with a rule above, a ledger's own convention. */
aggregate: boolean; dimension: Dimension } | { kind: "error"; error: CalcError };

export type CalcRow = {
	line: CalcLine,
	spans: CalcSpan[],
	/**  What `en` or `à` was asked to convert: the editor proposes the units of that kind. */
	converting: Dimension | null,
};

export type CalcSheet = {
	rows: CalcRow[],
	variables: CalcVariable[],
};

/**  What the editor colours, in UTF-16 units from the start of the line. */
export type CalcSpan = {
	start: number,
	end: number,
	kind: TokenKind,
};

/**  One unit, or one over another: `€/h`. */
export type CalcUnit = {
	unit: UnitId,
	per: UnitId | null,
};

/**  Exact decimals as text: a float would round them before the front decides how to. */
export type CalcValue = { kind: "number"; value: string; unit: CalcUnit | null } | 
/**  `value` in percent: `25` for 25 %. `signed` for a change, written `+25 %`. */
{ kind: "percent"; value: string; signed: boolean } | { kind: "date"; date: string } | 
/**  A duration in a unit and the next one down: `6 sem 3 j`. */
{ kind: "span"; parts: SpanPart[] } | 
/**  `255 en hex`: the digits `FF` in base 16, the front writing `0x` before them. */
{ kind: "base"; digits: string; radix: number; negative: boolean } | 
/**  `5300 en sci`: `5.3` times ten to the 3. */
{ kind: "scientific"; mantissa: string; exponent: number } | 
/**  `2/10 en fraction`: `1/5`, reduced. */
{ kind: "fraction"; numerator: string; denominator: string; negative: boolean } | 
/**  `20/5 en multiple`: `×4`. */
{ kind: "multiplier"; value: string };

/**
 *  A name, the line it was given on, its value there and the lines that read it before it
 *  was given another. Zero-based lines.
 */
export type CalcVariable = {
	name: string,
	line: number,
	value: CalcValue,
	uses: number[],
};

/**  What a calendar counts: whole months first, each of its own length, then the wall clock. */
export type CalendarGap = {
	years: number,
	months: number,
	days: number,
	hours: number,
	minutes: number,
	seconds: number,
};

export type CardNetwork = "visa" | "mastercard" | "americanExpress" | "discover" | "dinersClub" | "jcb" | "unionPay" | "maestro";

/**
 *  One loose card that moved. Filing is not here: it goes through `file_notes`, whose answer
 *  the undo puts back. A position has no undo of its own.
 */
export type CardPlacement = {
	noteId: string,
	position: BoardPoint,
};

export type CaseAnswer = {
	/**  Empty for a text without a word. */
	conversions: CaseConversion[],
	/**  What the converters work from: the first line holding a word, or the whole phrase. */
	words: string[],
	/**  For a URL: transliterated, where the code cases only strip accents. Empty for no word. */
	slug: string,
};

export type CaseConversion = {
	case: TextCase,
	group: CaseGroup,
	value: string,
};

/**
 *  What a case is for. The code cases strip accents when asked; the text cases keep them, and
 *  keep the apostrophe that binds an elided word to the next (`l'été`).
 */
export type CaseGroup = "code" | "text";

export type CaseRequest = {
	text: string,
	/**  The code cases only: `été` is `ete` in `snake_case` and stays `été` in a title. */
	stripAccents: boolean,
	/**  Each line on its own; off, the whole text is one phrase. */
	perLine: boolean,
	titleCaseLanguage: TitleLanguage,
	slug: SlugOptions,
};

export type ChangelogRelease = {
	/**  `0.1.1`, or whatever the heading names. Square brackets are dropped. */
	version: string,
	/**  `None` when the heading carries no date; never invented. */
	date: string | null,
	sections: ChangelogSection[],
};

/**  One `### ` heading, or the anonymous one a release with no category gets.        */
export type ChangelogSection = {
	/**  Empty for that anonymous category: the front then renders no heading. */
	title: string,
	items: ChangelogSpan[][],
};

export type ChangelogSpan = {
	kind: SpanKind,
	text: string,
};

export type CharacterSet = "lowercase" | "uppercase" | "digits" | "symbols";

export type CheckAnswer = { kind: "luhn"; grouped: string; 
/**  Its digits, counted. */
length: number; valid: boolean; 
/**  The last digit the rest asks for. */
expectedLast: number; 
/**  The number with a check digit appended, as if it had none yet. */
completed: string; network: CardNetwork | null; guessed: boolean } | { kind: "iban"; country: string; printed: string; 
/**  The two digits after the country, as typed. */
checkDigits: string; 
/**  Its characters, spaces left out. */
length: number; verdict: IbanVerdict; guessed: boolean } | 
/**  One-based, in characters. */
{ kind: "unreadable"; at: number } | { kind: "tooShort" };

export type CheckKind = "luhn" | "iban";

export type CheckRequest = {
	text: string,
	/**  Read as this kind rather than by its shape. */
	kind: CheckKind | null,
};

/**
 *  No identifier: the position is the identity — `note_items` is keyed on
 *  `(note_id, position)`, and a write rewrites the whole list.
 */
export type ChecklistItem = {
	text: string,
	done: boolean,
};

export type CidrAnswer = {
	block: CidrBlock | null,
	problem: CidrProblem | null,
	membership: CidrMembership,
	/**  The prefixes offered as chips: the next three. */
	splitChoices: number[],
	split: CidrSplit | null,
	masks: MaskRow[],
	plan: CidrPlan | null,
	summary: CidrSummary | null,
};

export type CidrBlock = {
	family: IpFamily,
	cidr: string,
	/**  The address as typed, host bits and all: what a prefix chosen in the table applies to. */
	typed: string,
	prefix: number,
	hostBits: number,
	/**  The address had host bits set: `cidr` is its network. */
	normalised: boolean,
	/**  The network address in binary, cut where the host bits start. */
	binaryNetwork: string,
	binaryHost: string,
	kind: BlockKind,
	/**  The special range the block lies in, when it names one: `10.0.0.0/8`. */
	range: string | null,
	network: string,
	/**  IPv4 only. */
	mask: string | null,
	inverseMask: string | null,
	first: string,
	last: string,
	/**  IPv4 from `/30` up: `/31` and `/32` have none, nor IPv6. */
	broadcast: string | null,
	/**  Decimal digits: an IPv6 count passes what a JSON number holds. */
	addresses: string,
	usable: string,
	forms: CidrForms,
};

export type CidrForms = {
	integer: string,
	/**  IPv4 in hexadecimal, IPv6 with every zero written out. */
	expanded: string,
	reverse: ReverseDns,
};

export type CidrMembership = { kind: "empty" } | { kind: "unreadable" } | { kind: "outside" } | 
/**  Counted from the network address, which is host 0. */
{ kind: "inside"; host: string };

export type CidrPlan = {
	/**  In address order, which is the largest need first; the unreadable lines last. */
	lines: PlanLine[],
	/**  What is left of the block, as the fewest blocks. */
	free: string[],
};

export type CidrProblem = "unreadable" | "prefixTooLong" | "maskWithHoles" | "wrongFamily";

export type CidrRequest = {
	network: string,
	/**  `None` reads the family from the text. */
	family: IpFamily | null,
	member: string,
	split: number | null,
	/**  One need a line, a name and a host count, placed in the block. */
	plan: string,
	/**  Blocks, addresses and ranges, one a line, summarised whatever the block. */
	list: string,
};

export type CidrSplit = {
	prefix: number,
	subnets: Subnet[],
	/**  How many past `SUBNETS_SHOWN`, in decimal digits. */
	more: string,
};

export type CidrSummary = {
	/**  IPv4 first, then IPv6, each when the list holds some. */
	families: FamilySummary[],
	unreadable: string[],
};

export type Class = "owner" | "group" | "others";

/**  A row of the grid: its four boxes are four booleans, not a state machine. */
export type ClassRights = {
	class: Class,
	read: boolean,
	write: boolean,
	execute: boolean,
	/**  Setuid for the owner, setgid for the group, the sticky bit for the others. */
	special: boolean,
};

/**
 *  What a target could not write, said by the front: wget, Java's client and `URLSession`
 *  build no multipart body.
 */
export type CodeNotice = "multipartUnsupported";

/**  The dialog's four switches, each its own. */
export type CodeOptions = {
	/**  Off, every `{{name}}` is written as typed. */
	resolveVariables: boolean,
	/**  A secret written in clear: the front asks first, every time. */
	includeSecrets: boolean,
	/**  A command line's arguments one a line: a program is laid out whatever it says. */
	multiline: boolean,
	followRedirects: boolean,
};

export type CodeRequestOf = CodeRequestOf_Serialize | CodeRequestOf_Deserialize;

export type CodeRequestOf_Deserialize = {
	target: CodeTarget,
	options: CodeOptions,
	kind: RequestKind,
	method: HttpMethod,
	document: RequestDocument_Deserialize,
	collectionId: string | null,
	folderId: string | null,
	environmentId: string | null,
};

export type CodeRequestOf_Serialize = {
	target: CodeTarget,
	options: CodeOptions,
	kind: RequestKind,
	method: HttpMethod,
	document: RequestDocument_Serialize,
	collectionId: string | null,
	folderId: string | null,
	environmentId: string | null,
};

/**  What the code is written for; the front lists them and names them. */
export type CodeTarget = "curl" | "httpie" | "wget" | "powershell" | "fetch" | "axios" | "undici" | "angular" | "requests" | "httpx" | "go" | "reqwest" | "java" | "okhttp" | "csharp" | "guzzle" | "ruby" | "swift" | "dart" | "elixir";

export type CodecDirection = "encode" | "decode";

export type ColourAnswer = {
	colour: ColourReading,
	against: ColourReading,
	contrast: Contrast | null,
};

export type ColourReading = { kind: "read"; given: Notation; notations: Notations; 
/**  What the window paints: in sRGB, always. */
swatch: string; 
/**  An OKLCH colour sRGB cannot show, brought inside at the same lightness and hue. */
outOfGamut: boolean } | { kind: "invalid" } | { kind: "empty" };

export type ColourRequest = {
	colour: string,
	/**  The background the contrast is measured on; empty for none. */
	against: string,
};

export type Company = {
	name: string,
	identifiers: Identifier[],
};

/**  The connections every estimate is also given for, by their rate in bits per second. */
export type Connection = "fibre" | "mobile4g" | "adsl";

export type ConnectionEstimate = {
	/**  `None` for the rate typed. */
	connection: Connection | null,
	/**  In bits per second, exact. */
	rate: string,
	span: TransferTime,
};

export type ConsoleEvent = {
	/**  The send it belongs to, under the id the front sent it with. */
	id: string,
	at: string,
	/**  The request sent, and in a run of several its iteration, from 1: the line's right column. */
	request: string,
	iteration: number | null,
	line: ConsoleLine,
};

export type ConsoleLine = 
/**  A request leaving: the send's own, or one a script sent (`by`). */
{ kind: "out"; method: string; url: string; headers: KeyValue[]; by: ConsoleOrigin | null } | { kind: "in"; status: number; reason: string; millis: number; size: number; by: ConsoleOrigin | null } | 
/**  What came back in place of an answer, as an error's code and the values it states. */
{ kind: "failed"; code: ErrorCode; params: { [key in string]: string }; by: ConsoleOrigin | null } | { kind: "log"; level: LogLevel; text: string; by: ConsoleOrigin | null } | 
/**  A test that failed. */
{ kind: "test"; name: string; expected: string | null; actual: string | null; message: string | null; by: ConsoleOrigin | null } | { kind: "stopped"; stop: ScriptStop } | 
/**  An extraction whose path led nowhere: its variable was left as it was. */
{ kind: "missed"; path: string; variable: string };

/**  The script a line comes from: its kind, and the request, folder or collection that holds it. */
export type ConsoleOrigin = {
	kind: ScriptKind,
	level: ScriptLevel,
	name: string,
};

/**
 *  What a collection or a folder hands its requests (#478, #484). Each field is
 *  `#[serde(default)]`: one added later needs no migration.
 */
export type ContainerSettings = ContainerSettings_Serialize | ContainerSettings_Deserialize;

/**
 *  What a collection or a folder hands its requests (#478, #484). Each field is
 *  `#[serde(default)]`: one added later needs no migration.
 */
export type ContainerSettings_Deserialize = {
	/**  `Inherit` on a collection is no auth at all: nothing is above it. */
	auth?: RequestAuth,
	headers?: KeyValue[],
	transport?: TransportSettings,
	/**  Over the environment's and the globals', under a folder's and a request's own. */
	variables?: Variable_Deserialize[],
	/**  Run around each request under it: before the request's own, and after it. */
	scripts?: RequestScripts,
	/**  The order the runner last left: the runner's to write, never the settings dialog's. */
	runOrder?: RunEntry[],
};

/**
 *  What a collection or a folder hands its requests (#478, #484). Each field is
 *  `#[serde(default)]`: one added later needs no migration.
 */
export type ContainerSettings_Serialize = {
	/**  `Inherit` on a collection is no auth at all: nothing is above it. */
	auth: RequestAuth,
	headers: KeyValue[],
	transport: TransportSettings,
	/**  Over the environment's and the globals', under a folder's and a request's own. */
	variables: Variable_Serialize[],
	/**  Run around each request under it: before the request's own, and after it. */
	scripts: RequestScripts,
	/**  The order the runner last left: the runner's to write, never the settings dialog's. */
	runOrder?: RunEntry[],
};

export type Contrast = {
	ratio: number | null,
	aa: TextSizes,
	aaa: TextSizes,
	/**  `None` once AAA holds for body text: nothing left to reach. */
	fix: ContrastFix | null,
};

/**  The nearest text colour that reaches the next level on this background, for body text. */
export type ContrastFix = { kind: "found"; level: WcagLevel; hex: string } | 
/**  Neither black nor white reaches it on this background. */
{ kind: "unreachable"; level: WcagLevel };

export type ConvertAnswer = { kind: "converted"; text: string; 
/**  The keys left out, as `JSONPath`s: a `null` TOML cannot write. */
dropped: string[] } | 
/**  The text given does not parse: one-based line and column, in characters. */
{ kind: "unreadable"; line: number; column: number } | 
/**  It parses, but the other format cannot hold it: `path` is a `JSONPath`. */
{ kind: "impossible"; crossing: Crossing; path: string };

export type ConvertRequest = {
	text: string,
	from: DataFormat,
	to: DataFormat,
};

/**  A `Set-Cookie`, its attributes named. */
export type Cookie = {
	name: string,
	value: string,
	domain: string | null,
	path: string | null,
	/**  As the server wrote it: `Max-Age` or `Expires`, whichever came. */
	expires: string | null,
	httpOnly: boolean,
	secure: boolean,
	sameSite: string | null,
	/**
	 *  The URL that answered with it, when it was set by a redirect on the way; `None` for one
	 *  the answer itself set.
	 */
	from?: string | null,
};

export type CookieDomain = {
	domain: string,
	cookies: StoredCookie[],
};

export type Country = "FR" | "BE" | "DE" | "ES" | "IT" | "PT" | "NL" | "CH" | "GB" | "PL" | "SE" | "US" | "CA";

export type CronAnswer = { kind: "read"; 
/**  What a macro stands for: `@daily` is `0 0 * * *`. */
expanded: string | null; fields: FieldReading[]; 
/**  Both day fields restricted: either one matching is enough, as in cron. */
bothDays: boolean; zone: string; runs: Run[]; check: CronCheck | null; 
/**  Asked for by an end, or by a start that does not read. */
window: CronWindow | null; 
/**  Now, in `zone`: what « today » and « Friday afternoon » are counted from. */
now: Run } | 
/**  `@reboot` runs when the machine starts: no time to give. */
{ kind: "reboot" } | { kind: "refused"; field: CronField | null; token: string; 
/**  One-based, in characters of the expression as typed. */
at: number; problem: CronProblem } | { kind: "unknownZone"; zone: string };

export type CronCheck = 
/**
 *  `before` and `after` are the nearest runs around a moment that is none: what a « no »
 *  leaves one asking.
 */
{ kind: "checked"; matches: boolean; at: string; before: Run | null; after: Run | null } | { kind: "unreadable"; at: number } | { kind: "skipped" };

export type CronField = "second" | "minute" | "hour" | "dayOfMonth" | "month" | "dayOfWeek";

export type CronProblem = "empty" | "fieldCount" | "unknownMacro" | "unknownName" | "notANumber" | "outOfRange" | "reversedRange" | "zeroStep" | 
/**  A special character this field does not take: `L` in the minutes. */
"notHere" | 
/**  Read here, refused by the scheduler: nothing more precise to say. */
"refused";

export type CronRequest = {
	expression: string,
	/**  `None` is the machine's zone. */
	zone: string | null,
	/**  A date to test against the expression, read in `zone`; empty asks nothing. */
	check: string,
	/**  Where the runs are listed from, read in `zone`; empty is now. */
	from?: string,
	/**  Where they stop; empty lists the next ten. */
	until?: string,
};

/**  The runs between two moments: « will this run on Friday afternoon? ». */
export type CronWindow = 
/**
 *  ⚠️ `total` is counted, never the length of a list: a window of a year at every minute
 *  holds half a million runs, and ten of them cross the bridge. `last` is empty when
 *  `first` is all of them.
 */
{ kind: "counted"; from: Run; until: Run; total: number; first: Run[]; last: Run[] } | { kind: "unreadable"; end: WindowEnd; at: number } | 
/**  A date out of range, or an hour a change of clocks skipped. */
{ kind: "skipped"; end: WindowEnd } | 
/**  The end is not after the start. */
{ kind: "backwards" } | { kind: "tooLong"; years: number };

export type Crossing = 
/**  TOML has no `null`, and one in a list cannot be left out without moving the others. */
"tomlNull" | 
/**  A TOML document is a table: its root cannot be a list or a value. */
"tomlRoot" | 
/**  An XML document has one root element: an object of one key. */
"xmlRoot" | 
/**  A key XML cannot take as an element or an attribute name. */
"xmlName" | 
/**  An `@attribute` holds a value, not an object or a list. */
"xmlAttribute";

export type DataFormat = "json" | "toml" | "xml" | "yaml";

export type DatedClaim = {
	name: string,
	iso: string,
	/**  For how long ago or how far off, which the page writes and ages. */
	epochMilliseconds: number | null,
};

export type DecodeAnswer = {
	readAs: ByteEncoding,
	/**  Read by its shape rather than as asked. */
	guessed: boolean,
	/**  The other readings its shape allows: `deadbeef` is hexadecimal and Base64 alike. */
	also: ByteEncoding[],
	decoded: DecodedBytes,
	/**  The media type its header declared, for a `data:` URI pasted whole. */
	dataUri: string | null,
	image: DecodedImage | null,
};

