"httpScript" | "httpScriptSkipped" | 
/**  `method` is what the script wrote. */
"httpScriptMethod" | 
/**  The scripts made the request one that a protected `environment` asks about: `method`. */
"httpScriptProtected" | 
/**  A run's data file: `fault` is `unreadable` or `empty`. */
"httpRunData";

